
all_passed=true

for i in {1..4}; do
  test_dir="Testcase$i"
    diff_dir="Testcase${i}Diff"
      tc_ok=true

        # Determine if any pair in the Testcase folder actually differs
          has_diffs=false
            for file1 in "$test_dir"/*.1.txt; do
                [ -e "$file1" ] || continue
                    file2="${file1/.1.txt/.2.txt}"
                        if [ -f "$file2" ]; then
                              if ! diff -u "$file1" "$file2" >/dev/null 2>&1; then
                                      has_diffs=true
                                              break
                                                    fi
                                                        fi
                                                          done

                                                            if [ "$has_diffs" = true ]; then
                                                                # Verify directory existence
                                                                    if [ ! -d "$diff_dir" ]; then
                                                                          echo "Error: Directory $diff_dir should exist" >&2
                                                                                tc_ok=false
                                                                                    else
                                                                                          # Check every file pair inside the directory
                                                                                                for file1 in "$test_dir"/*.1.txt; do
                                                                                                        [ -e "$file1" ] || continue
                                                                                                                file2="${file1/.1.txt/.2.txt}"
                                                                                                                        base_name="$(basename "$file1" .1.txt)"
                                                                                                                                out_file="$diff_dir/${base_name}Diff.txt"

                                                                                                                                        if [ -f "$file2" ]; then
                                                                                                                                                  if ! diff -u "$file1" "$file2" >/dev/null 2>&1; then
                                                                                                                                                              # Pair differs: output file must exist with correct diff output (ignoring headers)
                                                                                                                                                                          if [ ! -f "$out_file" ]; then
                                                                                                                                                                                        echo "Error: Expected output file $out_file missing" >&2
                                                                                                                                                                                                      tc_ok=false
                                                                                                                                                                                                                  else
                                                                                                                                                                                                                                expected_diff=$(diff -u "$file1" "$file2" | tail -n +3)
                                                                                                                                                                                                                                              actual_diff=$(tail -n +3 "$out_file")
                                                                                                                                                                                                                                                            if [ "$expected_diff" != "$actual_diff" ]; then
                                                                                                                                                                                                                                                                            echo "Error: Contents of $out_file do not match expected diff" >&2
                                                                                                                                                                                                                                                                                            tc_ok=false
                                                                                                                                                                                                                                                                                                          fi
                                                                                                                                                                                                                                                                                                                      fi
                                                                                                                                                                                                                                                                                                                                else
                                                                                                                                                                                                                                                                                                                                            # Pair is identical: output file must not exist
                                                                                                                                                                                                                                                                                                                                                        if [ -f "$out_file" ]; then
                                                                                                                                                                                                                                                                                                                                                                      echo "Error: $out_file exists, but $file1 and $file2 are identical" >&2
                                                                                                                                                                                                                                                                                                                                                                                    tc_ok=false
                                                                                                                                                                                                                                                                                                                                                                                                fi
                                                                                                                                                                                                                                                                                                                                                                                                          fi
                                                                                                                                                                                                                                                                                                                                                                                                                  fi
                                                                                                                                                                                                                                                                                                                                                                                                                        done
                                                                                                                                                                                                                                                                                                                                                                                                                            fi
                                                                                                                                                                                                                                                                                                                                                                                                                              else
                                                                                                                                                                                                                                                                                                                                                                                                                                  # No differences found: directory must not exist
                                                                                                                                                                                                                                                                                                                                                                                                                                      if [ -d "$diff_dir" ]; then
                                                                                                                                                                                                                                                                                                                                                                                                                                            echo "Error: Directory $diff_dir should not exist" >&2
                                                                                                                                                                                                                                                                                                                                                                                                                                                  tc_ok=false
                                                                                                                                                                                                                                                                                                                                                                                                                                                      fi
                                                                                                                                                                                                                                                                                                                                                                                                                                                        fi

                                                                                                                                                                                                                                                                                                                                                                                                                                                          # Output exact required line format
                                                                                                                                                                                                                                                                                                                                                                                                                                                            if [ "$tc_ok" = true ]; then
                                                                                                                                                                                                                                                                                                                                                                                                                                                                echo "Testcase$i: PASS"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                  else
                                                                                                                                                                                                                                                                                                                                                                                                                                                                      echo "Testcase$i: FAIL"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                          all_passed=false
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            fi
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            done

                                                                                                                                                                                                                                                                                                                                                                                                                                                                            # Exit with status 0 if all pass, non-zero otherwise
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if [ "$all_passed" = true ]; then
                                                                                                                                                                                                                                                                                                                                                                                                                                                                              exit 0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                              else
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                exit 1
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                fi
